Your expense tracker is ready below. Add each spend with a note, category, amount and date, and it shows your total, what's left of your budget and a split by category. Everything resets when you close the chat, so it won't be saved for next month.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:16px;color:#222;max-width:560px}
  h2{margin:0 0 12px}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}
  input,select,button{padding:8px;font-size:14px;border:1px solid #bbb;border-radius:6px}
  button{background:#2563eb;color:#fff;border:none;cursor:pointer}
  button.del{background:#e5e7eb;color:#444;padding:4px 8px}
  .card{border:1px solid #ddd;border-radius:10px;padding:12px;margin-bottom:12px}
  .big{font-size:24px;font-weight:600}
  .muted{color:#666;font-size:13px}
  .bar{height:10px;background:#e5e7eb;border-radius:5px;overflow:hidden;margin-top:6px}
  .fill{height:100%;background:#2563eb;width:0}
  .over{background:#dc2626}
  .cat{display:flex;justify-content:space-between;font-size:14px;margin-top:6px}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="muted">Spent this month</div>
  <div class="big" id="total">₹0</div>
  <div class="muted" id="left">Set a budget to see what is left</div>
  <div class="bar"><div class="fill" id="fill"></div></div>
  <div class="row" style="margin-top:10px">
    <input type="number" id="budget" placeholder="Monthly budget (₹)" min="0">
    <button id="setBudget">Set budget</button>
  </div>
</div>

<div class="card">
  <div class="row">
    <input type="text" id="note" placeholder="What did you spend on?">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
  </div>
  <div class="row">
    <input type="number" id="amt" placeholder="Amount (₹)" min="0">
    <input type="date" id="date">
    <button id="add">Add</button>
  </div>
  <div class="muted" id="msg"></div>
</div>

<div class="card">
  <b>By category</b>
  <div id="cats" class="muted">Nothing yet</div>
</div>

<div class="card">
  <b>All expenses</b>
  <div id="list" class="muted">Nothing yet</div>
</div>

<script>
var items = [];
var budget = 0;
var $ = function(id){ return document.getElementById(id); };
function fmt(n){ return '₹' + Math.round(n).toLocaleString('en-IN'); }

$('date').value = new Date().toISOString().slice(0,10);

function render(){
  var total = 0, byCat = {};
  items.forEach(function(e){
    total += e.amt;
    byCat[e.cat] = (byCat[e.cat] || 0) + e.amt;
  });
  $('total').textContent = fmt(total);

  var fill = $('fill');
  if (budget > 0){
    var left = budget - total;
    $('left').textContent = left >= 0 ? fmt(left) + ' left of ' + fmt(budget) : fmt(-left) + ' over your ' + fmt(budget) + ' budget';
    fill.style.width = Math.min(100, total / budget * 100) + '%';
    fill.className = total > budget ? 'fill over' : 'fill';
  } else {
    $('left').textContent = 'Set a budget to see what is left';
    fill.style.width = '0';
  }

  var catBox = $('cats');
  catBox.textContent = '';
  var names = Object.keys(byCat).sort(function(a,b){ return byCat[b] - byCat[a]; });
  if (!names.length){ catBox.textContent = 'Nothing yet'; }
  names.forEach(function(n){
    var d = document.createElement('div');
    d.className = 'cat';
    var a = document.createElement('span'); a.textContent = n;
    var b = document.createElement('span'); b.textContent = fmt(byCat[n]) + ' (' + Math.round(byCat[n] / total * 100) + '%)';
    d.appendChild(a); d.appendChild(b);
    var bar = document.createElement('div'); bar.className = 'bar';
    var f = document.createElement('div'); f.className = 'fill'; f.style.width = (byCat[n] / total * 100) + '%';
    bar.appendChild(f);
    catBox.appendChild(d); catBox.appendChild(bar);
  });

  var list = $('list');
  list.textContent = '';
  if (!items.length){ list.textContent = 'Nothing yet'; }
  items.slice().sort(function(a,b){ return a.date < b.date ? 1 : -1; }).forEach(function(e){
    var r = document.createElement('div'); r.className = 'item';
    var l = document.createElement('span');
    l.textContent = e.date + ' · ' + e.note + ' (' + e.cat + ')';
    var rt = document.createElement('span');
    var amt = document.createElement('b'); amt.textContent = fmt(e.amt) + ' ';
    var x = document.createElement('button'); x.className = 'del'; x.textContent = 'Remove';
    x.onclick = function(){ items = items.filter(function(i){ return i.id !== e.id; }); render(); };
    rt.appendChild(amt); rt.appendChild(x);
    r.appendChild(l); r.appendChild(rt);
    list.appendChild(r);
  });
}

var nextId = 1;
$('add').onclick = function(){
  var amt = parseFloat($('amt').value);
  var note = $('note').value.trim();
  if (!(amt > 0)){ $('msg').textContent = 'Enter an amount above 0.'; return; }
  items.push({ id: nextId++, note: note || 'Expense', cat: $('cat').value, amt: amt, date: $('date').value });
  $('note').value = ''; $('amt').value = ''; $('msg').textContent = '';
  render();
};
$('setBudget').onclick = function(){
  budget = parseFloat($('budget').value) || 0;
  render();
};
render();
</script>
</body>
</html>
```
